import { CloseButton, FillPreview, Tooltip } from '@wix/design-system';
import { DismissSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import { TRANSPARENT_HEX_COLOR } from './../../../../../_shared/colors.js';

import { DELETE_SWATCH_BUTTON, SWATCH, SWATCH_TOOLTIP } from '../../data-hooks.js';
import classes from './single-color-swatch-scss.js';

interface SingleColorSwatchProps {
  fill: string;
  selectedColor: string | undefined;
  onClick: (color: string) => void;
  onMouseEnter?: (color: string) => void;
  onMouseLeave?: () => void;
  onDelete?: (color: string) => void;
  className?: string;
  onFocus?: () => void;
  setRef?: (ref: HTMLDivElement | null) => void;
  index?: string;
}

export const SingleColorSwatch: React.FC<SingleColorSwatchProps> = ({
  fill,
  selectedColor,
  onClick,
  onMouseEnter,
  onMouseLeave,
  onDelete,
  className,
  onFocus,
  setRef,
  index,
}) => {
  const { t, portal } = useContext(RicosContext);
  const [isHovered, setIsHovered] = useState(false);
  const isTransparent = fill === TRANSPARENT_HEX_COLOR;
  const tooltipContent = isTransparent ? t('ColorPicker_RemoveColor_Tooltip') : fill;
  const showDeleteButton = Boolean(onDelete) && !isTransparent && isHovered;

  return (
    <div
      className={classes.container}
      ref={setRef}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <Tooltip
        appendTo={portal}
        fixed
        content={tooltipContent}
        dataHook={SWATCH_TOOLTIP}
        enterDelay={1000}
        size="small"
        placement="top"
        moveBy={{ y: 10 }}
        className={className}
      >
        <FillPreview
          id={index}
          selected={selectedColor?.toUpperCase() === fill.toUpperCase()}
          aria-selected={selectedColor?.toUpperCase() === fill.toUpperCase()}
          onClick={e => {
            e.preventDefault();
            e.stopPropagation();
            onClick(fill);
          }}
          onMouseEnter={() => onMouseEnter?.(fill)}
          onMouseLeave={onMouseLeave}
          fill={isTransparent ? undefined : fill}
          dataHook={SWATCH}
          onFocus={onFocus}
          aria-label={`${fill} color swatch`}
          tabIndex={-1}
          role="option"
        />
      </Tooltip>

      {showDeleteButton && (
        <CloseButton
          className={classes.deleteButton}
          dataHook={DELETE_SWATCH_BUTTON}
          aria-label={t('DeleteButton_Tooltip')}
          skin="standardFilled"
          size="small"
          onMouseDown={event => {
            event.stopPropagation();
          }}
          onClick={event => {
            event.preventDefault();
            event.stopPropagation();
            onMouseLeave?.();
            onDelete?.(fill);
          }}
        >
          <DismissSmall />
        </CloseButton>
      )}
    </div>
  );
};
