// Pure PM-doc layer: range finding, grouping, tracked-group reconciliation,
// preview synthesis. No DOM, no view. `tiptap.ts` consumes this to build
// decorations and drive the widget controller.

import { Mark_Type } from './../../ricos-types/index.js';
import type { Mark, MarkType, Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import type { EditorState, Transaction } from './../../tiptap/pm/state.js';
import { ReplaceStep } from './../../tiptap/pm/transform.js';

import { DEFAULT_STYLE } from './defaults.js';
import {
  canMergeAdjacentByStructure,
  getAnnotationSignature,
  isCrossParagraphMergeStyle,
} from './merge-rules.js';

export type AnnotationRange = { from: number; to: number; mark: Mark };
export type AnnotationGroup = { sig: string; mark: Mark; ranges: AnnotationRange[] };
// `lcaStart` anchors the widget inside the first sub-range's textblock so
// upstream reflow shifts the SVG via CSS without a re-measure. `wrapTo` ends
// the wrap-sensitive zone (last sub-range's textblock); edits outside
// `[lcaStart, wrapTo]` skip reconcile.
export type TrackedAnnotationGroup = AnnotationGroup & {
  id: string;
  lcaStart: number;
  wrapTo: number;
};

export type PreviewOverride = {
  from: number;
  to: number;
  style: string;
  color: string;
  animate: boolean;
};

// Real tracked groups use `rn-${N}` (auto-incrementing), so this never collides.
const PREVIEW_WIDGET_KEY = 'rn-preview';

const getTextblockDepth = ($pos: ReturnType<ProseMirrorNode['resolve']>): number => {
  for (let depth = $pos.depth; depth > 0; depth--) {
    if ($pos.node(depth).isTextblock) {
      return depth;
    }
  }
  return 0;
};

const computeLca = (
  doc: ProseMirrorNode,
  ranges: AnnotationRange[]
): { start: number; wrapTo: number } => {
  let minFrom = Number.POSITIVE_INFINITY;
  let maxTo = Number.NEGATIVE_INFINITY;
  for (const range of ranges) {
    if (range.from < minFrom) {
      minFrom = range.from;
    }
    if (range.to > maxTo) {
      maxTo = range.to;
    }
  }
  // Clamp: `doc.resolve` throws on out-of-bounds.
  const safeFrom = Math.max(0, Math.min(minFrom, doc.content.size));
  const safeTo = Math.max(0, Math.min(maxTo, doc.content.size));
  const $from = doc.resolve(safeFrom);
  // First sub-range's textblock, not the doc-level LCA — using the doc LCA
  // for cross-paragraph ranges would disable the reconcile skip entirely.
  const depth = getTextblockDepth($from);
  const start = depth > 0 ? $from.start(depth) : 0;
  const $to = doc.resolve(safeTo);
  const toDepth = getTextblockDepth($to);
  const wrapTo = toDepth > 0 ? $to.end(toDepth) : doc.content.size;
  return { start, wrapTo };
};

const enrichWithLca = (
  doc: ProseMirrorNode,
  group: AnnotationGroup & { id: string }
): TrackedAnnotationGroup => {
  const lca = computeLca(doc, group.ranges);
  return {
    ...group,
    lcaStart: lca.start,
    wrapTo: lca.wrapTo,
  };
};

// NONE has no overlay; CLASSIC uses text-color's flat background.
export const isOverlayPreviewStyle = (style: string): boolean =>
  style !== 'NONE' && style !== 'CLASSIC';

export const isTrackedAnnotationGroupContainedInPreview = (
  trackedGroup: TrackedAnnotationGroup,
  previewOverride: PreviewOverride
): boolean =>
  trackedGroup.ranges.every(
    range => range.from >= previewOverride.from && range.to <= previewOverride.to
  );

// Without splitting, `Range.getClientRects()` on a multi-block range yields
// container-width rects for interior blocks (preview spans edge-to-edge
// instead of hugging text). Real ranges are per-text-node so never cross blocks.
const splitPreviewByTextblocks = (
  doc: ProseMirrorNode,
  from: number,
  to: number
): { from: number; to: number }[] => {
  const ranges: { from: number; to: number }[] = [];
  doc.nodesBetween(from, to, (node, pos) => {
    if (!node.isTextblock) {
      return true;
    }
    const blockStart = pos + 1;
    const blockEnd = pos + node.nodeSize - 1;
    const rangeStart = Math.max(from, blockStart);
    const rangeEnd = Math.min(to, blockEnd);
    if (rangeStart < rangeEnd) {
      ranges.push({ from: rangeStart, to: rangeEnd });
    }
    return false;
  });
  return ranges;
};

// Preview-only tracked annotation groups: one per textblock, run through the same
// merge rules a commit would, so preview grouping matches the eventual mark.
// The mark is fabricated (never enters the doc or undo history).
export const buildSyntheticPreviewTrackedGroups = (
  state: EditorState,
  override: PreviewOverride
): TrackedAnnotationGroup[] => {
  const markType = state.schema.marks[Mark_Type.SKETCH];
  if (!markType) {
    return [];
  }
  const subRanges = splitPreviewByTextblocks(state.doc, override.from, override.to);
  if (subRanges.length === 0) {
    return [];
  }
  const mark = markType.create({
    style: override.style,
    color: override.color,
    animate: override.animate,
  });
  const annotationRanges: AnnotationRange[] = subRanges.map(({ from, to }) => ({ from, to, mark }));
  const groups = groupAdjacentAnnotationRanges(state.doc, annotationRanges);
  // Stable per-group ids so widget DOM is reused across hovers.
  return groups.map((group, index) =>
    enrichWithLca(state.doc, {
      ...group,
      id: groups.length === 1 ? PREVIEW_WIDGET_KEY : `${PREVIEW_WIDGET_KEY}-${index}`,
    })
  );
};

const hasOnlyAllowedInlineGap = (
  doc: ProseMirrorNode,
  from: number,
  to: number,
  style: string
): boolean => {
  if (from >= to) {
    return true;
  }
  const allowHardBreak = isCrossParagraphMergeStyle(style);
  let hasContent = false;
  doc.nodesBetween(from, to, node => {
    if (hasContent) {
      return false;
    }
    if (node.isText) {
      hasContent = !!node.text;
      return false;
    }
    if (node.isLeaf) {
      if (allowHardBreak && node.type.name === 'hardBreak') {
        return false;
      }
      hasContent = true;
      return false;
    }
    return true;
  });
  return !hasContent;
};

const isSameInlineParent = (
  doc: ProseMirrorNode,
  previousRange: AnnotationRange,
  nextFrom: number
) => {
  const previousParent = doc.resolve(previousRange.from).parent;
  const nextParent = doc.resolve(nextFrom).parent;
  return previousParent === nextParent && previousParent.inlineContent;
};

const canExtendAnnotationRange = (
  doc: ProseMirrorNode,
  range: AnnotationRange,
  nextFrom: number,
  nextMark: Mark
) =>
  nextMark.eq(range.mark) &&
  isSameInlineParent(doc, range, nextFrom) &&
  hasOnlyAllowedInlineGap(doc, range.to, nextFrom, range.mark.attrs?.style || DEFAULT_STYLE);

// Fast-path gate: a tx with no inserted sketch marks can't
// introduce a new tracked group — only remap existing ones.
export const transactionInsertsSketchMark = (tr: Transaction, markType: MarkType): boolean => {
  for (const step of tr.steps) {
    if (!(step instanceof ReplaceStep) || step.slice.size === 0) {
      continue;
    }
    let found = false;
    step.slice.content.descendants(node => {
      if (found) {
        return false;
      }
      if (node.marks.some(mark => mark.type === markType)) {
        found = true;
        return false;
      }
      return true;
    });
    if (found) {
      return true;
    }
  }
  return false;
};

// Inline edits can alter tracked-group structure without inserting a mark:
// unmarked text gets absorbed (via `to` assoc=-1), Shift+Enter splits stroke
// styles, and gap-content changes can enable/break a future merge. The fast
// path only remaps positions, so detect these cases up front.
export const transactionTouchesTrackedGroup = (
  tr: Transaction,
  trackedGroups: TrackedAnnotationGroup[]
): boolean => {
  if (trackedGroups.length === 0) {
    return false;
  }
  // Union span (not per-group) so we catch gap edits that affect re-merge.
  let overallFrom = Number.POSITIVE_INFINITY;
  let overallTo = Number.NEGATIVE_INFINITY;
  for (const tracked of trackedGroups) {
    const groupFrom = tracked.ranges[0]!.from;
    const groupTo = tracked.ranges[tracked.ranges.length - 1]!.to;
    if (groupFrom < overallFrom) {
      overallFrom = groupFrom;
    }
    if (groupTo > overallTo) {
      overallTo = groupTo;
    }
  }
  for (let stepIndex = 0; stepIndex < tr.steps.length; stepIndex++) {
    const step = tr.steps[stepIndex];
    if (!(step instanceof ReplaceStep)) {
      continue;
    }
    // step positions live in `tr.docs[stepIndex]`; invert mapping to compare
    // against the unmapped tracked groups.
    const inverse = tr.mapping.slice(0, stepIndex).invert();
    const stepFromInPriorDoc = inverse.map(step.from);
    const stepToInPriorDoc = inverse.map(step.to);
    if (stepFromInPriorDoc <= overallTo && stepToInPriorDoc >= overallFrom) {
      return true;
    }
  }
  return false;
};

export const findAnnotationRanges = (state: EditorState): AnnotationRange[] => {
  const markType = state.schema.marks[Mark_Type.SKETCH];
  if (!markType) {
    return [];
  }

  const ranges: AnnotationRange[] = [];
  const activeRef: { current: AnnotationRange | null } = { current: null };

  state.doc.descendants((node, pos) => {
    if (!node.isText) {
      return true;
    }

    const mark = node.marks.find(m => m.type === markType);
    if (!mark) {
      if (activeRef.current) {
        ranges.push(activeRef.current);
        activeRef.current = null;
      }
      return true;
    }

    const nodeFrom = pos;
    const nodeTo = pos + node.nodeSize;
    const active = activeRef.current;

    if (active && canExtendAnnotationRange(state.doc, active, nodeFrom, mark)) {
      active.to = nodeTo;
      return true;
    }

    if (active) {
      ranges.push(active);
    }
    activeRef.current = { from: nodeFrom, to: nodeTo, mark };
    return true;
  });

  if (activeRef.current) {
    ranges.push(activeRef.current);
  }

  return ranges;
};

const getParagraphInfo = (doc: ProseMirrorNode, pos: number) => {
  const $pos = doc.resolve(pos);
  for (let depth = $pos.depth; depth > 0; depth--) {
    if ($pos.node(depth).type.name.toLowerCase() === 'paragraph') {
      return {
        depth,
        start: $pos.before(depth),
        parent: $pos.node(depth - 1),
      };
    }
  }
  return null;
};

const canMergeAnnotationRanges = (
  doc: ProseMirrorNode,
  previousRange: AnnotationRange,
  range: AnnotationRange,
  style: string
) => {
  const previousInfo = getParagraphInfo(doc, previousRange.from);
  const info = getParagraphInfo(doc, range.from);
  if (!previousInfo || !info) {
    return false;
  }
  if (!hasOnlyAllowedInlineGap(doc, previousRange.to, range.from, style)) {
    return false;
  }
  return canMergeAdjacentByStructure(style, {
    sameBlock: previousInfo.depth === info.depth && previousInfo.start === info.start,
    // Identity-compare naturally rejects different list items / table cells.
    sameStructuralContainer: previousInfo.parent === info.parent,
  });
};

const groupAdjacentAnnotationRanges = (
  doc: ProseMirrorNode,
  ranges: AnnotationRange[]
): AnnotationGroup[] => {
  const groups: AnnotationGroup[] = [];
  for (const range of ranges) {
    const sig = getAnnotationSignature(range.mark.attrs ?? {});
    const style = range.mark.attrs?.style || DEFAULT_STYLE;
    const previousGroup = groups[groups.length - 1];
    const previousRange = previousGroup?.ranges[previousGroup.ranges.length - 1];
    if (
      previousGroup &&
      previousRange &&
      previousGroup.sig === sig &&
      canMergeAnnotationRanges(doc, previousRange, range, style)
    ) {
      previousGroup.ranges.push(range);
      continue;
    }
    groups.push({ sig, mark: range.mark, ranges: [range] });
  }
  return groups;
};

export const buildAnnotationGroups = (state: EditorState): AnnotationGroup[] =>
  groupAdjacentAnnotationRanges(state.doc, findAnnotationRanges(state));

// Text-only join (no sig) — id+seed stay stable while user adjusts attrs.
export const buildAnnotationGroupText = (doc: ProseMirrorNode, group: AnnotationGroup) =>
  group.ranges.map(range => doc.textBetween(range.from, range.to, '\n', '\n')).join('\n');

const annotationRangesOverlap = (
  first: { from: number; to: number },
  second: { from: number; to: number }
) => first.from < second.to && first.to > second.from;

const annotationGroupMatchesTrackedGroup = (
  doc: ProseMirrorNode,
  group: AnnotationGroup,
  tracked: TrackedAnnotationGroup
) =>
  buildAnnotationGroupText(doc, group) === buildAnnotationGroupText(doc, tracked) &&
  group.ranges.some(groupRange =>
    tracked.ranges.some(trackedGroup => annotationRangesOverlap(groupRange, trackedGroup))
  );

export const reconcileTrackedAnnotationGroups = (
  state: EditorState,
  previousTrackedGroups: TrackedAnnotationGroup[],
  nextRangeId: number
): { trackedGroups: TrackedAnnotationGroup[]; nextRangeId: number } => {
  const groups = buildAnnotationGroups(state);
  const claimedPreviousIds = new Set<string>();
  const trackedGroups = groups.map(group => {
    const previous = previousTrackedGroups.find(
      candidate =>
        !claimedPreviousIds.has(candidate.id) &&
        annotationGroupMatchesTrackedGroup(state.doc, group, candidate)
    );
    if (previous) {
      claimedPreviousIds.add(previous.id);
      return enrichWithLca(state.doc, { ...group, id: previous.id });
    }
    const id = `rn-${nextRangeId}`;
    nextRangeId++;
    return enrichWithLca(state.doc, { ...group, id });
  });
  return { trackedGroups, nextRangeId };
};

// Map tracked-group positions through a transaction. `to` uses assoc=-1 so
// insertions AT the boundary stay outside the range (otherwise typing right
// after marked text would push `to` past the new content and the SVG would
// visually "swallow" unmarked text). `from` uses default assoc=1 for the
// mirror reason.
export const mapTrackedGroupPositions = (
  tr: Transaction,
  trackedGroups: TrackedAnnotationGroup[]
): TrackedAnnotationGroup[] =>
  trackedGroups.map(trackedGroup => ({
    ...trackedGroup,
    ranges: trackedGroup.ranges.map(range => ({
      ...range,
      from: tr.mapping.map(range.from),
      to: tr.mapping.map(range.to, -1),
    })),
  }));

// Fast path: drop ranges fully deleted by the mapping and recompute LCA
// bounds against the new doc. Used when the tx provably can't have altered
// tracked-group structure (inline-text-only, no inserted mark, no edit
// touching a tracked region).
export const applyFastPathReconcile = (
  doc: ProseMirrorNode,
  mappedTrackedGroups: TrackedAnnotationGroup[]
): TrackedAnnotationGroup[] => {
  const survivingTrackedRanges: TrackedAnnotationGroup[] = [];
  for (const group of mappedTrackedGroups) {
    const filteredRanges = group.ranges.filter(range => range.from < range.to);
    if (filteredRanges.length === 0) {
      continue;
    }
    survivingTrackedRanges.push(enrichWithLca(doc, { ...group, ranges: filteredRanges }));
  }
  return survivingTrackedRanges;
};
