import type { ColorPickerProps } from '@wix/design-system';
import { Box, ColorPicker as ColorPickerBase, Divider, Text } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useEffect, useMemo, useState } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import type { ThemeColorSwatch } from './../../../../../_shared/color-manager-utils.js';
import { TRANSPARENT_HEX_COLOR } from './../../../../../_shared/colors.js';
import { resolveColorToDisplayHex } from './../../../../../_shared/resolve-color-to-display-hex.js';
import {
  isThemeColorToken,
  themeColorTokenToHex,
  type ThemeColorToken,
} from './../../../../../_shared/theme-color-token.js';
import {
  getHexColorFromAlpha,
  getOpacityFromHex,
  resolveColorsPalette,
} from './../../../../../wix-rich-content-common/index.js';
import { usePanelContainerElement } from './../../../../ui-components-provider.js';

import { CUSTOM_SWATCHES, SIMPLE_COLOR_PICKER, THEME_SWATCHES } from '../../data-hooks.js';
import { NewColorSwatches } from '../new-color-swatches/new-color-swatches.js';
import classes from './simple-color-picker-scss.js';

type SimpleColorPickerProps = {
  currentColor: string | undefined;
  themeColors: ThemeColorSwatch[];
  customColors: string[];
  onColorSelected: (color: string | undefined) => void;
  onColorPreview?: (color: string | undefined) => void;
  onColorPreviewStart?: (color: string | undefined) => void;
  onColorPreviewEnd?: () => void;
  onColorAdded?: (color: string) => void;
  onColorDeleted?: (color: string) => void;
  allowTransparent?: boolean;
};

const THEME_COLORS_GRID_ID = 'simple-picker-theme-colors-grid';
const SAVED_COLORS_GRID_ID = 'simple-picker-saved-colors-grid';

const getColorHex = (color: ColorPickerProps['value']): string =>
  typeof color === 'string' ? color : color.hex();

export const SimpleColorPicker: FC<SimpleColorPickerProps> = ({
  currentColor,
  themeColors,
  customColors,
  onColorSelected,
  onColorPreview,
  onColorPreviewStart,
  onColorPreviewEnd,
  onColorAdded,
  onColorDeleted,
  allowTransparent,
}) => {
  const { t, theme } = useContext(RicosContext);
  const palette = theme.colorPalette;
  const panelContainerEl = usePanelContainerElement();
  const [containerElement, setContainerElement] = useState<HTMLDivElement | null>(null);
  const colorResolverElement = panelContainerEl ?? containerElement;

  const resolveThemeTokenToHex = (token: ThemeColorToken): string | undefined => {
    if (!palette) {
      return undefined;
    }
    return themeColorTokenToHex(token, palette)?.toUpperCase();
  };

  const resolvedThemeColors: ThemeColorSwatch[] = useMemo(
    () =>
      themeColors.flatMap(swatch => {
        const hex = resolveColorToDisplayHex(swatch.hex, colorResolverElement);
        return hex ? [{ ...swatch, hex }] : [];
      }),
    [themeColors, colorResolverElement]
  );

  // The swatch component identifies clicks by hex; map back to the token so a
  // theme-swatch click emits the semantic token regardless of identical hexes
  // appearing in the custom-color section.
  const themeHexToToken = useMemo(() => {
    const map = new Map<string, ThemeColorToken>();
    for (const swatch of resolvedThemeColors) {
      if (swatch.token) {
        map.set(swatch.hex.toUpperCase(), swatch.token);
      }
    }
    return map;
  }, [resolvedThemeColors]);

  const resolvedCurrentColor =
    currentColor && isThemeColorToken(currentColor) && palette
      ? resolveThemeTokenToHex(currentColor)
      : currentColor;

  const isTransparentColor = getOpacityFromHex(resolvedCurrentColor) === 0;
  const isCurrentColorToken = !!currentColor && isThemeColorToken(currentColor);
  const currentColorAsHex = isTransparentColor
    ? undefined
    : getHexColorFromAlpha(resolvedCurrentColor)?.toUpperCase();
  const pickerDisplayColor = currentColorAsHex ?? '';
  // Highlight is driven by the stored selection's *kind*: a token highlights a
  // theme swatch, a literal hex highlights a saved swatch. This lets the user
  // distinguish a theme-bound color from a hardcoded hex even when they look
  // identical.
  const selectedThemeSwatchColor = isCurrentColorToken ? currentColorAsHex : undefined;
  const selectedSavedSwatchColor = isTransparentColor
    ? TRANSPARENT_HEX_COLOR
    : isCurrentColorToken
      ? undefined
      : currentColorAsHex;

  const [pickerColor, setPickerColor] = useState(pickerDisplayColor);

  useEffect(() => {
    setPickerColor(pickerDisplayColor);
  }, [pickerDisplayColor]);

  const setPickerColorFromSwatch = (color: string | undefined) => {
    setPickerColor(
      getOpacityFromHex(color) === 0 ? '' : (getHexColorFromAlpha(color)?.toUpperCase() ?? '')
    );
  };

  const usesDeferredCommit = Boolean(onColorPreview);
  const pendingColorRef = React.useRef<string | undefined>(pickerDisplayColor || undefined);
  const isDraggingRef = React.useRef(false);
  const removeDragEndListenersRef = React.useRef<(() => void) | undefined>(undefined);

  useEffect(
    () => () => {
      removeDragEndListenersRef.current?.();
    },
    []
  );

  const commitColor = (color: string | undefined) => {
    isDraggingRef.current = false;
    pendingColorRef.current = color;
    onColorSelected(color);
  };

  const handleColorChange = (newColor: ColorPickerProps['value']) => {
    const color = getColorHex(newColor);
    setPickerColor(color);
    pendingColorRef.current = color;

    if (usesDeferredCommit) {
      onColorPreview?.(color);
      return;
    }

    onColorSelected(color);
    onColorPreviewStart?.(color);
  };

  const handleColorAdd = (newColor: ColorPickerProps['value']) => {
    const color = getColorHex(newColor);
    if (!color) {
      return;
    }
    setPickerColor(color);
    commitColor(color);

    if (onColorAdded && !customColors.includes(color.toUpperCase())) {
      onColorAdded(color.toUpperCase());
    }
  };

  const handleThemeSwatchSelected = (color: string | undefined) => {
    setPickerColorFromSwatch(color);
    const token = color ? themeHexToToken.get(color.toUpperCase()) : undefined;
    commitColor(token ?? color);
  };

  const handleSavedSwatchSelected = (color: string | undefined) => {
    setPickerColorFromSwatch(color);
    commitColor(color);
  };

  const handleSwatchPreviewStart = (color: string | undefined) => {
    if (usesDeferredCommit) {
      onColorPreview?.(color);
    }
    onColorPreviewStart?.(color);
  };

  const handlePickerPointerUp = () => {
    if (!usesDeferredCommit || !isDraggingRef.current) {
      return;
    }

    commitColor(pendingColorRef.current);
  };

  // In deferred-commit mode a typed color only previews (WDS fires `onChange`
  // per keystroke, and its Enter-confirm is unusable here because hiding the
  // action buttons makes WDS auto-confirm on every change). Commit the pending
  // color ourselves when the user presses Enter in the hex input.
  const handlePickerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (
      !usesDeferredCommit ||
      event.key !== 'Enter' ||
      !(event.target instanceof HTMLInputElement)
    ) {
      return;
    }

    const color = pendingColorRef.current;
    if (!color) {
      return;
    }

    commitColor(color);
    if (onColorAdded && !customColors.includes(color.toUpperCase())) {
      onColorAdded(color.toUpperCase());
    }
  };

  const handleColorDeleted = (color: string) => {
    onColorDeleted?.(color.toUpperCase());
  };

  // WDS keeps the hex input focused during picker drag
  const handleColorPickerInteractionStart = (event: React.PointerEvent<HTMLDivElement>) => {
    const activeElement = event.currentTarget.ownerDocument.activeElement;

    if (
      activeElement instanceof HTMLInputElement &&
      event.currentTarget.contains(activeElement) &&
      event.target !== activeElement
    ) {
      activeElement.blur();
    }

    if (!usesDeferredCommit) {
      return;
    }

    removeDragEndListenersRef.current?.();
    isDraggingRef.current = true;
    const ownerDocument = event.currentTarget.ownerDocument;

    const handleDocumentPointerUp = () => {
      removeDragEndListenersRef.current?.();

      if (!isDraggingRef.current) {
        return;
      }

      commitColor(pendingColorRef.current);
    };

    removeDragEndListenersRef.current = () => {
      ownerDocument.removeEventListener('pointerup', handleDocumentPointerUp, true);
      ownerDocument.removeEventListener('pointercancel', handleDocumentPointerUp, true);
      removeDragEndListenersRef.current = undefined;
    };

    ownerDocument.addEventListener('pointerup', handleDocumentPointerUp, true);
    ownerDocument.addEventListener('pointercancel', handleDocumentPointerUp, true);
  };

  const savedColors = [
    ...(allowTransparent ? [TRANSPARENT_HEX_COLOR] : []),
    ...resolveColorsPalette(customColors, undefined),
  ];

  const hasThemeColors = resolvedThemeColors.length > 0;
  const hasSavedColors = savedColors.length > 0;

  return (
    <div className={classes.container} data-hook={SIMPLE_COLOR_PICKER} ref={setContainerElement}>
      <Box
        direction="vertical"
        paddingTop="SP3"
        paddingLeft="SP4"
        paddingRight="SP4"
        paddingBottom="SP3"
        gap="SP2"
      >
        <div
          className={classes.colorPicker}
          onPointerDown={handleColorPickerInteractionStart}
          onPointerUp={handlePickerPointerUp}
          onKeyDown={handlePickerKeyDown}
        >
          <Box align="center">
            <ColorPickerBase
              allowEmpty
              value={pickerColor}
              showConverter={false}
              showEyeDropper
              showActionButtons={false}
              onChange={handleColorChange}
              onAdd={handleColorAdd}
              addTooltipContent={t('ColorPickerAddCustomColor_Tooltip')}
              emptyPlaceholder={t('CustomColorPicker_Empty_Placeholder')}
            />
          </Box>
        </div>

        {hasThemeColors && (
          <NewColorSwatches
            colors={resolvedThemeColors.map(swatch => swatch.hex)}
            selectedColor={selectedThemeSwatchColor}
            onColorSelected={handleThemeSwatchSelected}
            onColorPreviewStart={handleSwatchPreviewStart}
            onColorPreviewEnd={onColorPreviewEnd}
            dataHook={THEME_SWATCHES}
            labelledById={THEME_COLORS_GRID_ID}
          />
        )}
      </Box>

      {hasSavedColors && (
        <>
          <Divider />

          <Box direction="vertical" padding="SP3" paddingLeft="SP4" paddingRight="SP4" gap="SP3">
            <Text size="small" weight="bold" id={SAVED_COLORS_GRID_ID}>
              {t('Color_Picker_SavedColor_Title')}
            </Text>
            <NewColorSwatches
              colors={savedColors}
              deletableColors={customColors}
              selectedColor={selectedSavedSwatchColor}
              onColorSelected={handleSavedSwatchSelected}
              onColorPreviewStart={handleSwatchPreviewStart}
              onColorPreviewEnd={onColorPreviewEnd}
              onColorDeleted={onColorDeleted ? handleColorDeleted : undefined}
              dataHook={CUSTOM_SWATCHES}
              labelledById={SAVED_COLORS_GRID_ID}
            />
          </Box>
        </>
      )}
    </div>
  );
};
