import {
  Accordion,
  Box,
  FormField,
  Text,
  Thumbnail,
  ToggleSwitch,
  accordionItemBuilder,
} from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useEffect, useRef, useState } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  ZIndexContext,
} from './../../../ricos-context/index.js';
import { Mark_Type } from './../../../ricos-types/index.js';
import { ColorWithOpacityInput } from './../../../ui-components/color-with-opacity-input/color-with-opacity-input.js';
import { Panel, PanelHeader } from './../../../ui-components/index.js';

import type { TextHighlightPluginEditorConfig } from '../../types.js';
import { DATA_HOOKS, SKETCH_COLOR_PICKER_MODAL_ID, SKETCH_DESIGN_MODAL_ID } from '../data-hooks.js';
import { DEFAULT_ANIMATE, DEFAULT_COLOR, DEFAULT_STYLE } from '../defaults.js';
import { DesignColorPicker } from './design-color-picker.js';
import { type DesignStyle, STYLE_GRID } from './style-grid.js';

const SectionTitle: FC<{ title: string }> = ({ title }) => (
  <Text size="small" weight="bold" ellipsis maxLines={1} showTooltip>
    {title}
  </Text>
);

type DesignSelectionState = { style: DesignStyle; color: string; animate: boolean };

const readSelectionState = (
  editor: ReturnType<typeof useEditorFromContext>
): DesignSelectionState => {
  const isRough = editor.isActive(Mark_Type.SKETCH);
  if (isRough) {
    const attrs = editor.getAttributes(Mark_Type.SKETCH) as {
      style?: DesignStyle;
      color?: string;
      animate?: boolean;
    };
    return {
      style: (attrs.style as DesignStyle) ?? DEFAULT_STYLE,
      color: attrs.color ?? DEFAULT_COLOR,
      animate: attrs.animate ?? DEFAULT_ANIMATE,
    };
  }
  const isClassic = editor.isActive(Mark_Type.COLOR_BACKGROUND);
  if (isClassic) {
    const attrs = editor.getAttributes(Mark_Type.COLOR_BACKGROUND) as { color?: string };
    return {
      style: 'CLASSIC',
      color: attrs.color ?? DEFAULT_COLOR,
      animate: false,
    };
  }
  return { style: 'NONE', color: DEFAULT_COLOR, animate: DEFAULT_ANIMATE };
};

const useEditorFromContext = () => {
  const { adapter } = useContext(EditorContext);
  return adapter.tiptapEditor;
};

// No `chain().focus()` here: focusing the editor from a modal handler
// collapses the text selection, so the next apply becomes a no-op. PM
// keeps the original selection regardless of DOM focus.
const useApplyStyle = () => {
  const { adapter } = useContext(EditorContext);
  const editor = adapter.tiptapEditor;

  return (style: DesignStyle, color: string, animate: boolean) => {
    const chain = editor.chain();

    chain.unsetMark(Mark_Type.SKETCH).unsetMark(Mark_Type.COLOR_BACKGROUND);

    if (style === 'NONE') {
      chain.run();
      return;
    }
    if (style === 'CLASSIC') {
      chain.setMark(Mark_Type.COLOR_BACKGROUND, { color }).run();
      return;
    }
    chain.setSketch({ style, color, animate }).run();
  };
};

const usePreviewStyle = () => {
  const { adapter } = useContext(EditorContext);
  const editor = adapter.tiptapEditor;

  return (style: DesignStyle, color: string, animate: boolean) => {
    const { from, to } = editor.state.selection;
    if (from === to) {
      return;
    }
    editor.commands.previewSketch({ from, to, style, color, animate });
    // CLASSIC isn't drawn by the rough overlay; paint a flat preview via text-color.
    editor.commands.previewHighlight(style === 'CLASSIC' ? color : null);
  };
};

const useClearPreview = () => {
  const { adapter } = useContext(EditorContext);
  const editor = adapter.tiptapEditor;
  return () => {
    editor.commands.clearSketchPreview();
    editor.commands.previewHighlight(null);
  };
};

export const SketchDesignModal: FC<{
  config?: TextHighlightPluginEditorConfig;
  referenceElement?: HTMLElement | null;
}> = ({ config = { type: 'textHighlight' }, referenceElement: _referenceElement }) => {
  const { isMobile, t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const modalService = useContext(ModalServiceContext);
  const editor = useEditorFromContext();
  const colorSwatchRef = useRef<HTMLDivElement>(null);
  const applyStyle = useApplyStyle();
  const previewStyle = usePreviewStyle();
  const clearPreview = useClearPreview();

  const [committed, setCommitted] = useState<DesignSelectionState>(() =>
    readSelectionState(editor)
  );
  const { style, color, animate } = committed;

  useEffect(() => {
    return () => {
      editor.commands.clearSketchPreview();
      editor.commands.previewHighlight(null);
    };
  }, [editor]);

  const onClose = () => {
    clearPreview();
    modalService.closeModal(SKETCH_COLOR_PICKER_MODAL_ID);
    modalService.closeModal(SKETCH_DESIGN_MODAL_ID);
  };

  const onColorSelected = (next: string | undefined) => {
    const nextColor = next ?? DEFAULT_COLOR;
    // Picking a color from a clean selection upgrades NONE to CLASSIC so the result is visible.
    const targetStyle = style === 'NONE' ? 'CLASSIC' : style;
    clearPreview();
    applyStyle(targetStyle, nextColor, animate);
    setCommitted({ style: targetStyle, color: nextColor, animate });
  };

  const onAnimateToggle = () => {
    if (style === 'NONE' || style === 'CLASSIC') {
      return;
    }
    clearPreview();
    applyStyle(style, color, !animate);
    setCommitted({ style, color, animate: !animate });
  };

  // Flat → rough transitions default to animate=true; the committed
  // `animate` flag is meaningless for flat states (toggle is disabled).
  const isFlat = (s: DesignStyle) => s === 'NONE' || s === 'CLASSIC';
  const animateForTransition = (next: DesignStyle): boolean => {
    if (isFlat(next)) {
      return false;
    }
    if (isFlat(committed.style)) {
      return true;
    }
    return animate;
  };

  const onHoverStyle = (hovered: DesignStyle) => {
    previewStyle(hovered, color, animateForTransition(hovered));
  };
  const onLeaveStyle = () => {
    clearPreview();
  };
  const onSelectStyle = (next: DesignStyle) => {
    const nextAnimate = animateForTransition(next);
    clearPreview();
    applyStyle(next, color, nextAnimate);
    setCommitted({ style: next, color, animate: nextAnimate });
  };

  const onColorPreviewStart = (next: string | undefined) => {
    if (next === undefined) {
      clearPreview();
      return;
    }
    const targetStyle = style === 'NONE' ? 'CLASSIC' : style;
    previewStyle(targetStyle, next, animate);
  };
  const onColorPreview = (next: string | undefined) => {
    if (next === undefined) {
      clearPreview();
      return;
    }
    const targetStyle = style === 'NONE' ? 'CLASSIC' : style;
    previewStyle(targetStyle, next, false);
  };
  const onColorPreviewEnd = () => {
    clearPreview();
  };

  const openColorPicker = () => {
    if (!colorSwatchRef.current) {
      return;
    }
    // Anchor the color picker to the Design panel itself (not the swatch
    // inside it) so its top edge aligns with the modal's top edge instead
    // of being pulled up to the swatch's vertical center.
    const designPanelEl = document.querySelector<HTMLElement>(
      `[data-hook~="${DATA_HOOKS.DESIGN_MODAL}"]`
    );
    const positioningRef = designPanelEl ?? colorSwatchRef.current;
    modalService.togglePluginPanel({
      id: SKETCH_COLOR_PICKER_MODAL_ID,
      Component: DesignColorPicker,
      componentProps: {
        config,
        modalId: SKETCH_COLOR_PICKER_MODAL_ID,
        currentColor: color,
        referenceElement: colorSwatchRef.current,
        onColorSelected,
        onColorPreview,
        onColorPreviewStart,
        onColorPreviewEnd,
      },
      isMobile,
      // 'right-start' carries a built-in `crossAxis: -78` offset (see
      // ricos-modals/components/floating.tsx) that shifts the panel UP —
      // good for popovers anchored to a small reference, wrong here. Use
      // the dedicated 'right-start--custom-offset' variant which maps to
      // floating-ui's 'right-start' (top-aligned) but skips the crossAxis
      // shift, so the picker's top sits flush with the modal's top.
      positioning: { referenceElement: positioningRef, placement: 'right-start--custom-offset' },
      onClickOutside: { on: 'pointerup', handler: () => {} },
      focusReturnElement: colorSwatchRef.current,
      type: undefined,
    });
  };

  const isStyled = style !== 'NONE' && style !== 'CLASSIC';

  return (
    <Panel closeButtonProps={{ onClick: onClose }} dataHook={DATA_HOOKS.DESIGN_MODAL}>
      <PanelHeader title={t('Sketch_DesignModal_Title')} />
      <Box direction="vertical">
        <Accordion
          hideShadow
          skin="light"
          size="medium"
          multiple
          items={[
            accordionItemBuilder({
              key: 'highlight-color',
              initiallyOpen: true,
              title: <SectionTitle title={t('Sketch_DesignModal_HighlightColor')} />,
              children: (
                <Box direction="vertical" gap="SP2">
                  <ColorWithOpacityInput
                    fill={{
                      type: 'color',
                      color,
                      onChange: onColorSelected,
                      onChangeCommit: onColorSelected,
                    }}
                    label={t('Sketch_DesignModal_Color')}
                    inputDataHook={DATA_HOOKS.COLOR_INPUT}
                    fillPreviewDataHook={DATA_HOOKS.COLOR_SWATCH}
                    onColorPress={openColorPicker}
                    colorPickerRef={colorSwatchRef}
                    zIndex={zIndexService.getZIndex('DIALOG')}
                  />
                </Box>
              ),
            }),
            accordionItemBuilder({
              key: 'decoration',
              initiallyOpen: true,
              title: <SectionTitle title={t('Sketch_DesignModal_Decoration')} />,
              children: (
                <Box direction="vertical" gap="SP3">
                  <FormField
                    label={t('Sketch_DesignModal_Animated')}
                    labelPlacement="left"
                    labelWidth="1fr"
                    labelAlignment="middle"
                  >
                    <ToggleSwitch
                      dataHook={DATA_HOOKS.ANIMATED_TOGGLE}
                      checked={isStyled && animate}
                      disabled={!isStyled}
                      onChange={onAnimateToggle}
                      size="small"
                    />
                  </FormField>

                  <div
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(3, 1fr)',
                      gap: '8px',
                      justifyItems: 'center',
                    }}
                  >
                    {STYLE_GRID.map(entry => (
                      <div key={entry.id}>
                        <Thumbnail
                          dataHook={entry.dataHook}
                          width={76}
                          height={76}
                          size="tiny"
                          textPosition="outside"
                          contentAlignment="center"
                          noPadding
                          ellipsis
                          maxLines={1}
                          selected={style === entry.id}
                          onClick={() => onSelectStyle(entry.id)}
                          title={t(entry.labelKey)}
                          image={
                            entry.Icon ? (
                              <entry.Icon
                                onMouseEnter={() => onHoverStyle(entry.id)}
                                onMouseLeave={onLeaveStyle}
                              />
                            ) : undefined
                          }
                        />
                      </div>
                    ))}
                  </div>
                </Box>
              ),
            }),
          ]}
        />
      </Box>
    </Panel>
  );
};
