import type { FC } from 'react';
import React, { useContext, useMemo } from 'react';

import { ModalServiceContext, RicosContext } from './../../../ricos-context/index.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded as addColorToManager,
  handleColorDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
} from './../../../_shared/color-manager-utils.js';
import { NewColorPicker } from './../../../ui-components/color-picker/new-color-picker/index.js';

import type { TextHighlightPluginEditorConfig } from '../../types.js';
import { DEFAULT_COLOR } from '../defaults.js';

type DesignColorPickerProps = {
  config: TextHighlightPluginEditorConfig;
  modalId: string;
  currentColor?: string;
  referenceElement: HTMLElement | undefined;
  onColorSelected: (color: string | undefined) => void;
  onColorPreview?: (color: string | undefined) => void;
  // Hover-preview callbacks the modal wires into the sketch
  // preview-overlay system. Forwarded straight to NewColorPicker so the
  // swatch's mouseenter / mouseleave paint and clear the preview without
  // touching the doc.
  onColorPreviewStart?: (color: string | undefined) => void;
  onColorPreviewEnd?: () => void;
};

export const DesignColorPicker: FC<DesignColorPickerProps> = ({
  config,
  modalId,
  currentColor,
  referenceElement,
  onColorSelected,
  onColorPreview,
  onColorPreviewStart,
  onColorPreviewEnd,
}) => {
  const modalService = useContext(ModalServiceContext);
  const { colorManager, t, theme } = useContext(RicosContext);

  const themeColors = useMemo(
    () =>
      resolveThemeColorsPalette(
        theme,
        config.colorScheme ? Object.values(config.colorScheme).map(c => c.color) : []
      ),
    [config.colorScheme, theme]
  );
  const customColors = useResolvedCustomColors(colorManager, config.getUserColors);

  const logBi = useBiNext({
    modalId,
    pluginId: 'textHighlight',
  });

  const onColorAdded = (color: string) => {
    addColorToManager(color, colorManager, config.onColorAdded);
    onColorSelected(color);
  };

  const onColorDeletedHandler = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const closeModal = () => modalService.closeModal(modalId);

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      currentColor={currentColor ?? DEFAULT_COLOR}
      title={t('Color_Picker_TextHighlightButton_Header')}
      closeModal={closeModal}
      onColorSelected={onColorSelected}
      onColorPreview={onColorPreview}
      onColorAdded={onColorAdded}
      onColorDeleted={colorManager || !config.getUserColors ? onColorDeletedHandler : undefined}
      onColorPreviewStart={onColorPreviewStart}
      onColorPreviewEnd={onColorPreviewEnd}
      onResetColor={() => onColorSelected(undefined)}
      referenceElement={referenceElement}
      logBi={logBi}
    />
  );
};
