import type { OpSet, ResolvedOptions } from 'roughjs/bin/core';

import type { SketchData_Variant } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { ITERATIONS, PADDING, STROKE_WIDTH, UNDERLINE_OFFSET } from './defaults.js';

export type Rect = { x: number; y: number; w: number; h: number };

export type ShapePath = { d: string; strokeWidth: number };

// Subset of `roughjs/bin/renderer` we depend on. The handle loads the module
// lazily and passes it in so this file stays free of side-effectful imports.
export type RendererModule = {
  line: (x1: number, y1: number, x2: number, y2: number, o: ResolvedOptions) => OpSet;
  rectangle: (x: number, y: number, w: number, h: number, o: ResolvedOptions) => OpSet;
  ellipse: (x: number, y: number, w: number, h: number, o: ResolvedOptions) => OpSet;
};

export type GenerateShapeArgs = {
  renderer: RendererModule;
  rect: Rect;
  style: SketchData_Variant | string;
  seed: number;
};

type Mode = 'highlight' | 'single' | 'double';

// Mirrors rough-annotation's `getOptions` (src/render.ts). Only CIRCLE uses
// 'double' (`disableMultiStroke: false`), which produces the classic
// double-traced hand-drawn circle. Everything else uses 'single', and
// HIGHLIGHT bumps roughness to 3 for a wider, scribblier sweep.
const buildOptions = (mode: Mode, seed: number): ResolvedOptions => ({
  maxRandomnessOffset: 2,
  roughness: mode === 'highlight' ? 3 : 1.5,
  bowing: 1,
  stroke: '#000',
  strokeWidth: 1.5,
  curveTightness: 0,
  curveFitting: 0.95,
  curveStepCount: 9,
  fillStyle: 'hachure',
  fillWeight: -1,
  hachureAngle: -41,
  hachureGap: -1,
  dashOffset: -1,
  dashGap: -1,
  zigzagOffset: -1,
  disableMultiStroke: mode !== 'double',
  disableMultiStrokeFill: false,
  preserveVertices: false,
  fillShapeRoughnessGain: 0.8,
  seed,
});

// Port of rough-annotation's `opsToPath` (src/render.ts). The key difference vs
// roughjs's own `RoughGenerator.opsToPath` is that this splits at every
// `move`, so each logical stroke ends up as its own `<path>` element. That's
// what lets the dasharray reveal animate each stroke on its own timeline
// instead of treating an `M…M…` multi-subpath as one continuous reveal.
// Width of the bounding box around all control points across all ops.
// We sample only the explicit endpoints / curve handles roughjs emits —
// good enough as a "did this curve come out wide enough?" check, far
// cheaper than getBBox() which would require DOM insertion.
const opsBoundingWidth = (opList: OpSet[]): number => {
  let minX = Infinity;
  let maxX = -Infinity;
  for (const drawing of opList) {
    for (const item of drawing.ops) {
      const data = item.data;
      for (let i = 0; i < data.length; i += 2) {
        const x = data[i];
        if (x === undefined) {
          continue;
        }
        if (x < minX) {
          minX = x;
        }
        if (x > maxX) {
          maxX = x;
        }
      }
    }
  }
  return maxX > minX ? maxX - minX : 0;
};

const opsToPath = (opList: OpSet[]): string[] => {
  const paths: string[] = [];
  for (const drawing of opList) {
    let path = '';
    for (const item of drawing.ops) {
      const data = item.data;
      switch (item.op) {
        case 'move':
          if (path.trim()) {
            paths.push(path.trim());
          }
          path = `M${data[0]} ${data[1]} `;
          break;
        case 'bcurveTo':
          path += `C${data[0]} ${data[1]}, ${data[2]} ${data[3]}, ${data[4]} ${data[5]} `;
          break;
        case 'lineTo':
          path += `L${data[0]} ${data[1]} `;
          break;
      }
    }
    if (path.trim()) {
      paths.push(path.trim());
    }
  }
  return paths;
};

// Alternating-direction strokes on a horizontal line: each pass traces back
// to the start so the dasharray reveal looks like one continuous hand-drawn
// line rather than parallel duplicates.
const pushAlternatingHorizontalStrokes = (
  ops: OpSet[],
  line: RendererModule['line'],
  rect: Rect,
  y: number,
  iterations: number,
  o: ResolvedOptions
) => {
  for (let i = 0; i < iterations; i++) {
    if (i % 2) {
      ops.push(line(rect.x + rect.w, y, rect.x, y, o));
    } else {
      ops.push(line(rect.x, y, rect.x + rect.w, y, o));
    }
  }
};

const collectOps = ({
  renderer,
  rect,
  style,
  seed,
}: GenerateShapeArgs): { ops: OpSet[]; strokeWidth: number } => {
  const { line, rectangle, ellipse } = renderer;
  const iterations = ITERATIONS;
  const o = buildOptions('single', seed);
  const ops: OpSet[] = [];
  let strokeWidth = STROKE_WIDTH;

  switch (style) {
    case 'UNDERLINE':
      pushAlternatingHorizontalStrokes(
        ops,
        line,
        rect,
        rect.y + rect.h + UNDERLINE_OFFSET,
        iterations,
        o
      );
      return { ops, strokeWidth };
    case 'STRIKETHROUGH':
      pushAlternatingHorizontalStrokes(ops, line, rect, rect.y + rect.h / 2, iterations, o);
      return { ops, strokeWidth };
    case 'CROSSED_OFF': {
      const { x, y } = rect;
      const x2 = x + rect.w;
      const y2 = y + rect.h;
      // Each iteration alternates direction along the SAME line so the
      // dasharray reveal traces back and forth — that's what makes
      // iterations=2 look like one continuous hand-drawn stroke rather than
      // two parallel duplicates.
      for (let i = 0; i < iterations; i++) {
        if (i % 2) {
          ops.push(line(x2, y2, x, y, o));
        } else {
          ops.push(line(x, y, x2, y2, o));
        }
      }
      for (let i = 0; i < iterations; i++) {
        if (i % 2) {
          ops.push(line(x, y2, x2, y, o));
        } else {
          ops.push(line(x2, y, x, y2, o));
        }
      }
      return { ops, strokeWidth };
    }
    case 'HIGHLIGHT': {
      const ho = buildOptions('highlight', seed);
      strokeWidth = rect.h * 0.95;
      const y = rect.y + rect.h / 2;
      for (let i = 0; i < iterations; i++) {
        if (i % 2) {
          ops.push(line(rect.x + rect.w, y, rect.x, y, ho));
        } else {
          ops.push(line(rect.x, y, rect.x + rect.w, y, ho));
        }
      }
      return { ops, strokeWidth };
    }
    case 'BOX': {
      const x = rect.x - PADDING;
      const y = rect.y - PADDING;
      const width = rect.w + 2 * PADDING;
      const height = rect.h + 2 * PADDING;
      for (let i = 0; i < iterations; i++) {
        ops.push(rectangle(x, y, width, height, o));
      }
      return { ops, strokeWidth };
    }
    case 'CIRCLE': {
      // Roughjs's `ellipse()` draws an ellipse INSCRIBED in (width, height)
      // and randomly perturbs each Bezier control point proportional to
      // `roughness`. With our roughness:1.5 + double-stroke mode, the
      // resulting curve width can swing ~12% across seeds — some seeds
      // produce a curve narrower than the marked text rect (visibly
      // cutting through the first/last visual line on multi-line wraps),
      // others produce one that wraps the text fine.
      //
      // We want to keep the natural hand-drawn variance for seeds that
      // already wrap the text, but boost the seeds that shrink below the
      // text rect. So we generate at the natural size first, measure the
      // resulting curve's bbox from its control points, and only retry
      // with an inflated input if the curve came out too small.
      const doubleO = buildOptions('double', seed);
      const cx = rect.x + rect.w / 2;
      const cy = rect.y + rect.h / 2;
      const fullItr = Math.floor(iterations / 2);
      const singleItr = iterations - fullItr * 2;
      const drawEllipse = (ellipseW: number, ellipseH: number): OpSet[] => {
        const out: OpSet[] = [];
        for (let i = 0; i < fullItr; i++) {
          out.push(ellipse(cx, cy, ellipseW, ellipseH, doubleO));
        }
        for (let i = 0; i < singleItr; i++) {
          out.push(ellipse(cx, cy, ellipseW, ellipseH, o));
        }
        return out;
      };
      const naturalW = rect.w + 2 * PADDING;
      const naturalH = rect.h + 2 * PADDING;
      let circleOps = drawEllipse(naturalW, naturalH);
      // Only inflate the seeds that drew too small to wrap the text rect.
      // This boosts the "shrinking" seeds toward the size of the wrapping
      // seeds, without growing seeds that already wrap correctly.
      const renderedW = opsBoundingWidth(circleOps);
      if (renderedW < rect.w) {
        const inflate = (rect.w + PADDING) / renderedW;
        circleOps = drawEllipse(naturalW * inflate, naturalH * inflate);
      }
      ops.push(...circleOps);
      return { ops, strokeWidth };
    }
    default:
      // Unknown style: fall back to BOX so nothing disappears silently.
      return collectOps({ renderer, rect, style: 'BOX', seed });
  }
};

// Produce one `<path>`-ready entry per logical stroke (one rect at a time).
// Multi-rect/multi-line cases are handled by the caller, mirroring how
// rough-annotation calls `renderAnnotation` once per client rect.
export const generateShapePaths = (args: GenerateShapeArgs): ShapePath[] => {
  const { ops, strokeWidth } = collectOps(args);
  return opsToPath(ops).map(d => ({ d, strokeWidth }));
};
